from __future__ import annotations

import itertools

EPS = 1e-6


def rins(values: dict[str, float], costs: dict[str, float], budget: float,
         incumbent: dict[str, int], x: dict[str, float]) -> list[str] | None:
    """The best plan among those that keep every variable the incumbent and the LP agree on."""
    fixed = {j: incumbent[j] for j in incumbent if abs(x[j] - incumbent[j]) < EPS}
    free = sorted(j for j in incumbent if j not in fixed)
    best, best_value = None, None
    for choice in itertools.product((0, 1), repeat=len(free)):
        plan = {**fixed, **dict(zip(free, choice))}
        if sum(costs[j] * plan[j] for j in plan) > budget:
            continue
        total = sum(values[j] * plan[j] for j in plan)
        if best_value is None or total > best_value:
            best, best_value = plan, total
    if best is None:
        return None
    return sorted(j for j in best if best[j])


if __name__ == "__main__":
    values, costs = {"A": 7, "B": 6, "C": 5, "D": 2}, {"A": 5, "B": 4, "C": 3, "D": 1}
    print(rins(values, costs, 9, {"A": 1, "B": 0, "C": 0, "D": 1}, {"A": 0.2, "B": 1, "C": 1, "D": 1}))
